<?php declare(strict_types=1);require_once __DIR__.'/../session-security.php';session_start();sessionSecurityEnforce();require_once __DIR__.'/../mapa/banco.php';require_once __DIR__.'/../auth.php';$pdo=db();authInit($pdo);if(!authLogged()){header('Location: ../login.php');exit;}authRequirePermission($pdo,'sistema.usuarios',false);$profiles=authProfileLabels();$perms=authPermissionCatalog();$users=$pdo->query("SELECT id,username,nome,role,professor_id,ativo,ultimo_login FROM usuarios_sistema ORDER BY nome")->fetchAll();$profs=$pdo->query("SELECT id,nome FROM professores ORDER BY nome")->fetchAll();
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administração • Liceu</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui;background:#f4f8fc;color:#17324d}.top{background:#075aa8;color:#fff;padding:16px 22px;display:flex;justify-content:space-between}.top a{color:#fff}.wrap{max-width:1180px;margin:auto;padding:24px}.grid{display:grid;grid-template-columns:330px 1fr;gap:16px}.card{background:#fff;border:1px solid #dce6f0;border-radius:14px;padding:16px}.user{padding:11px;border:1px solid #e4ebf2;border-radius:10px;margin:7px 0;cursor:pointer}.user:hover{border-color:#75afe0}.muted{color:#718096;font-size:12px}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:5px}input,select{width:100%;padding:10px;border:1px solid #ccd8e5;border-radius:9px}.btn{border:0;border-radius:9px;padding:10px 13px;font-weight:800;cursor:pointer}.primary{background:#075aa8;color:#fff}.perm{display:grid;grid-template-columns:1fr 180px;gap:10px;align-items:center;border-top:1px solid #edf1f5;padding:9px 0}.perm select{padding:7px}.critical{background:#fff8e8;padding:8px;border-radius:8px}.notice{padding:10px;background:#eaf4ff;border-radius:9px;font-size:12px;margin-bottom:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}.row{grid-template-columns:1fr}.perm{grid-template-columns:1fr}}</style></head><body><div class="top"><b>Administração de Acessos</b><a href="../index.php">← Central de Apps</a></div><main class="wrap"><div class="notice">Perfil = pacote padrão. Exceção individual pode liberar ou bloquear uma função para apenas um login. Administração Suprema permanece crítica e auditada.</div><div class="grid"><section class="card"><h3>Usuários</h3><button class="btn primary" onclick="novo()">+ Novo usuário</button><div id="users"><?php foreach($users as$u):?><div class="user" onclick='editar(<?=json_encode($u,JSON_HEX_APOS|JSON_HEX_QUOT)?>)'><b><?=htmlspecialchars($u['nome'])?></b><div class="muted"><?=htmlspecialchars($profiles[$u['role']]??$u['role'])?> • @<?=htmlspecialchars($u['username'])?><?=$u['ativo']?'':' • INATIVO'?></div></div><?php endforeach?></div></section><section class="card"><h3 id="titulo">Novo usuário</h3><input type="hidden" id="id"><div class="row"><div class="field"><label>Nome</label><input id="nome"></div><div class="field"><label>Usuário</label><input id="username"></div><div class="field"><label>Perfil</label><select id="role"><?php foreach($profiles as$k=>$v):?><option value="<?=$k?>"><?=htmlspecialchars($v)?></option><?php endforeach?></select></div><div class="field"><label>Professor vinculado (se perfil Professor)</label><select id="professor"><option value="">— Nenhum —</option><?php foreach($profs as$p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nome'])?></option><?php endforeach?></select></div><div class="field"><label>Senha <?= ' (preencha para criar/trocar)' ?></label><input id="senha" type="password" autocomplete="new-password"></div><div class="field"><label>Status</label><select id="ativo"><option value="1">Ativo</option><option value="0">Inativo</option></select></div></div><button class="btn primary" onclick="salvarUsuario()">Salvar usuário</button><h3 style="margin-top:24px">Exceções individuais</h3><div class="muted">“Padrão do perfil” usa a regra do cargo. Liberado/Bloqueado vale apenas para este usuário.</div><div id="perms"><?php foreach($perms as$k=>$v):?><div class="perm <?=$k==='mapa.admin_supremo'?'critical':''?>"><div><b><?=htmlspecialchars($v)?></b><div class="muted"><?=htmlspecialchars($k)?></div></div><select data-perm="<?=htmlspecialchars($k)?>"><option value="0">Padrão do perfil</option><option value="1">Liberado individualmente</option><option value="-1">Bloqueado individualmente</option></select></div><?php endforeach?></div><button class="btn primary" style="margin-top:12px" onclick="salvarPerms()">Salvar exceções</button></section></div></main><script>
let atual=null;const $=id=>document.getElementById(id);function novo(){atual=null;$('id').value='';$('nome').value='';$('username').value='';$('role').value='recepcao';$('professor').value='';$('senha').value='';$('ativo').value='1';$('titulo').textContent='Novo usuário';document.querySelectorAll('[data-perm]').forEach(x=>x.value='0')}async function editar(u){atual=u;$('id').value=u.id;$('nome').value=u.nome;$('username').value=u.username;$('role').value=u.role;$('professor').value=u.professor_id||'';$('senha').value='';$('ativo').value=u.ativo?'1':'0';$('titulo').textContent=u.nome;const r=await fetch('api.php?action=permissoes&userId='+u.id);const j=await r.json();document.querySelectorAll('[data-perm]').forEach(x=>x.value=String((j.overrides||{})[x.dataset.perm]||0))}async function post(action,data){const r=await fetch('api.php?action='+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Erro');return j}async function salvarUsuario(){try{await post('salvar_usuario',{id:+$('id').value||0,nome:$('nome').value,username:$('username').value,role:$('role').value,professorId:+$('professor').value||null,senha:$('senha').value,ativo:+$('ativo').value});alert('Usuário salvo.');location.reload()}catch(e){alert(e.message)}}async function salvarPerms(){if(!$('id').value)return alert('Salve ou selecione um usuário primeiro.');const overrides={};document.querySelectorAll('[data-perm]').forEach(x=>overrides[x.dataset.perm]=+x.value);try{await post('salvar_permissoes',{userId:+$('id').value,overrides});alert('Permissões atualizadas.')}catch(e){alert(e.message)}}novo();</script></body></html>
